import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import DangNhap from './trang/DangNhap';

// Trang Dashboard tạm thời (Sau này bạn sẽ tách ra file riêng)
const Dashboard = () => (
    <div style={{ padding: '50px', textAlign: 'center' }}>
        <h1>Chào mừng bạn đến với Dashboard!</h1>
        <p>Đây là trang quản lý chính của hệ thống A&RMS.</p>
    </div>
);

function App() {
  return (
    <Router>
      <Routes>
        {/* Đường dẫn mặc định vào thẳng trang đăng nhập */}
        <Route path="/" element={<Navigate to="/auth" />} />

        {/* Trang đăng nhập/đăng ký */}
        <Route path="/auth" element={<DangNhap />} />

        {/* Trang Dashboard - Sau khi login thành công sẽ nhảy vào đây */}
        <Route path="/dashboard" element={<Dashboard />} />
      </Routes>
    </Router>
  );
}

export default App;
